CREATE VIEW "customer_list" ("ID", "name", "address", "zip code", "phone", "city", "country", "notes", "SID") AS
SELECT "cu"."customer_id" AS "ID", "cu"."first_name" || ' ' || "cu"."last_name" AS "name", "a"."address" AS "address", "a"."postal_code" AS "zip code", "a"."phone" AS "phone", "city"."city" AS "city", "country"."country" AS "country", IIF("cu"."active", 'active', '') AS "notes", "cu"."store_id" AS "SID" FROM ((("customer" AS "cu" JOIN "address" AS "a" ON (("cu"."address_id" = "a"."address_id"))) JOIN "city" ON (("a"."city_id" = "city"."city_id"))) JOIN "country" ON (("city"."country_id" = "country"."country_id")));

CREATE VIEW "film_list" ("FID", "title", "description", "category", "price", "length", "rating", "actors") AS
SELECT "film"."film_id" AS "FID", "film"."title" AS "title", "film"."description" AS "description", "category"."name" AS "category", "film"."rental_rate" AS "price", "film"."length" AS "length", "film"."rating" AS "rating", GROUP_CONCAT("actor"."first_name" || ' ' || "actor"."last_name", ', ') AS "actors" FROM (((("film" LEFT JOIN "film_category" ON (("film_category"."film_id" = "film"."film_id"))) LEFT JOIN "category" ON (("category"."category_id" = "film_category"."category_id"))) LEFT JOIN "film_actor" ON (("film"."film_id" = "film_actor"."film_id"))) LEFT JOIN "actor" ON (("film_actor"."actor_id" = "actor"."actor_id"))) GROUP BY "film"."film_id", "category"."name";

CREATE VIEW "nicer_but_slower_film_list" ("FID", "title", "description", "category", "price", "length", "rating", "actors") AS
SELECT "film"."film_id" AS "FID", "film"."title" AS "title", "film"."description" AS "description", "category"."name" AS "category", "film"."rental_rate" AS "price", "film"."length" AS "length", "film"."rating" AS "rating", GROUP_CONCAT(UPPER(SUBSTRING("actor"."first_name", 1, 1)) || LOWER(SUBSTRING("actor"."first_name", 2, LENGTH("actor"."first_name"))) || ' ' || UPPER(SUBSTRING("actor"."last_name", 1, 1)) || LOWER(SUBSTRING("actor"."last_name", 2, LENGTH("actor"."last_name"))), ', ') AS "actors" FROM (((("film" LEFT JOIN "film_category" ON (("film_category"."film_id" = "film"."film_id"))) LEFT JOIN "category" ON (("category"."category_id" = "film_category"."category_id"))) LEFT JOIN "film_actor" ON (("film"."film_id" = "film_actor"."film_id"))) LEFT JOIN "actor" ON (("film_actor"."actor_id" = "actor"."actor_id"))) GROUP BY "film"."film_id", "category"."name";

CREATE VIEW "sales_by_film_category" ("category", "total_sales") AS
SELECT "c"."name" AS "category", SUM("p"."amount") AS "total_sales" FROM ((((("payment" AS "p" JOIN "rental" AS "r" ON (("p"."rental_id" = "r"."rental_id"))) JOIN "inventory" AS "i" ON (("r"."inventory_id" = "i"."inventory_id"))) JOIN "film" AS "f" ON (("i"."film_id" = "f"."film_id"))) JOIN "film_category" AS "fc" ON (("f"."film_id" = "fc"."film_id"))) JOIN "category" AS "c" ON (("fc"."category_id" = "c"."category_id"))) GROUP BY "c"."name" ORDER BY "total_sales" DESC;

CREATE VIEW "sales_by_store" ("store", "manager", "total_sales") AS
SELECT "c"."city" || ',' || "cy"."country" AS "store", "m"."first_name" || ' ' || "m"."last_name" AS "manager", SUM("p"."amount") AS "total_sales" FROM ((((((("payment" AS "p" JOIN "rental" AS "r" ON (("p"."rental_id" = "r"."rental_id"))) JOIN "inventory" AS "i" ON (("r"."inventory_id" = "i"."inventory_id"))) JOIN "store" AS "s" ON (("i"."store_id" = "s"."store_id"))) JOIN "address" AS "a" ON (("s"."address_id" = "a"."address_id"))) JOIN "city" AS "c" ON (("a"."city_id" = "c"."city_id"))) JOIN "country" AS "cy" ON (("c"."country_id" = "cy"."country_id"))) JOIN "staff" AS "m" ON (("s"."manager_staff_id" = "m"."staff_id"))) GROUP BY "s"."store_id" ORDER BY "cy"."country", "c"."city";

CREATE VIEW "staff_list" ("ID", "name", "address", "zip code", "phone", "city", "country", "SID") AS
SELECT "s"."staff_id" AS "ID", "s"."first_name" || ' ' || "s"."last_name" AS "name", "a"."address" AS "address", "a"."postal_code" AS "zip code", "a"."phone" AS "phone", "city"."city" AS "city", "country"."country" AS "country", "s"."store_id" AS "SID" FROM ((("staff" AS "s" JOIN "address" AS "a" ON (("s"."address_id" = "a"."address_id"))) JOIN "city" ON (("a"."city_id" = "city"."city_id"))) JOIN "country" ON (("city"."country_id" = "country"."country_id")));

